// === Tab: main.js ===
/*
Noise Field Skyline

Controls:
  - Left-click to change image
  - Hold right-click to show particles only
	- Move mouse over particles to interact with them

jasonlabbe3d.com
twitter.com/russetPotato
*/

var noiseScale = 0.005;
var repulsionRadius = 100;
var imgNames = ["ny.jpg", "hk.jpg", "sg.jpg"]; // Add your image's name here.

var imgs = [];
var imgIndex = -1;
var particles = [];
var seed = 0;


function preload() {
	for (let i = 0; i < imgNames.length; i++) {
		imgs.push(loadImage(imgNames[i]));
	}
}


function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);
	changeImage();
}


function draw() {
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == RIGHT) {
		background(255);
	}

	let img = imgs[imgIndex];

	// Pick a random point on the image.
	let rad = 100;
	let speed = 0.02;
	let x = 20;
	let y = abs(sin(frameCount * 0.01)) * img.height;
	particles.push(new Particle(x, y));

	for (let i = particles.length - 1; i > -1 ; i--) {
		particles[i].move();
		particles[i].display();

		if (particles[i].outOfBounds()) {
			particles.splice(i, 1);
		}
	}

	if (frameCount % 100 == 0) {
		seed++;
	}
}


function changeImage() {
	background(255);

	imgIndex++;
	if (imgIndex >= imgNames.length) {
		imgIndex = 0;
	}

	imgs[imgIndex].loadPixels();
}


function mousePressed() {
	if (mouseButton == LEFT) {
		changeImage();
	}
}

// === Tab: particle.js ===
function Particle(x, y) {

  this.pos = new p5.Vector(x, y);
	this.lastPos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);
	this.speed = random(0.05, 0.2);
	this.size = random(5, 15);
  this.seed = seed;

	this.getColorByPos = function() {
		var img = imgs[imgIndex];
		let index = (int(this.pos.y) * img.width + int(this.pos.x)) * 4;

		let r = img.pixels[index];
		let g = img.pixels[index + 1];
		let b = img.pixels[index + 2];

		return [r, g, b];
	}

	this.outOfBounds = function() {
		var img = imgs[imgIndex];

		return (
			this.pos.x < 0 || 
			this.pos.x > img.width || 
			this.pos.y < 0 || 
			this.pos.y > img.height);
	}

  this.move = function() {
		this.lastPos.set(this.pos.x, this.pos.y);

		noiseSeed(this.seed);
		let n = noise(this.pos.x * noiseScale, this.pos.y * noiseScale);
		let moving = new p5.Vector(this.speed, 0);
		moving.rotate(radians(map(n, 0, 1, -120, 120)));
		this.acc.add(moving);

		let mouseDistance = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		if (mouseDistance < repulsionRadius) {
			let repulse = new p5.Vector(this.pos.x, this.pos.y);
			repulse.sub((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
			repulse.mult(map(mouseDistance, 100, 0, 0, 0.01));
			this.acc.add(repulse);
		}

    this.vel.mult(0.95);

    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  this.display = function() {
    let rgb = this.getColorByPos();
		fill(rgb[0], rgb[1], rgb[2]);
		stroke(0, 20);

		let direction = this.pos.copy();
		direction.sub(this.lastPos);
		direction.normalize();

		push();
		translate(this.pos.x, this.pos.y);
		rotate(direction.heading() + radians(-90));

		triangle(
			-this.size * 0.25, -this.size * 0.25,
			0, this.size * 1.5,
			this.size * 0.25, -this.size * 0.25);

		pop();
  }
}

